export async function fetchTasks(): Promise<Task[]> {
  const { user, isGuest } = getAuthState()
  if (isGuest || !user) return getTasks()

  try {
    const { token } = getAuthState()
    const headers: any = {}
    if (token) headers["Authorization"] = `Bearer ${token}`

    const response = await fetch(`${API_URL}/users/${user.id}/tasks`, { headers })
    if (response.ok) {
      const data = await response.json()
      return data.map((t: any) => ({
        id: t.id.toString(),
        title: t.title,
        completed: t.is_completed,
        createdAt: new Date(t.created_at)
      }))
    }
  } catch (error) {
    console.error("Failed to fetch tasks", error)
  }
  return []
}

export async function createTask(title: string): Promise<Task | null> {
  const { user, isGuest, token } = getAuthState()

  if (isGuest || !user) {
    const newTask: Task = {
      id: Date.now().toString(),
      title,
      completed: false,
      createdAt: new Date()
    }
    const tasks = getTasks()
    saveTasks([...tasks, newTask])
    return newTask
  }

  if (!token) {
    console.error("createTask: User is logged in but token is missing from AuthState!")
    // Temporarily return null or throw to avoid 401
    return null
  }

  try {
    const headers: any = {
      "Content-Type": "application/json",
      "Authorization": `Bearer ${token}`
    }

    // Debug log to confirm token is being used
    console.log("createTask: Sending request with token:", token.substring(0, 10) + "...")

    const response = await fetch(`${API_URL}/tasks`, {
      method: "POST",
      headers,
      body: JSON.stringify({ user_id: user.id, title })
    })
    if (response.ok) {
      const t = await response.json()
      return {
        id: t.id.toString(),
        title: t.title,
        completed: t.is_completed,
        createdAt: new Date(t.created_at)
      }
    }
  } catch (error) {
    console.error("Failed to create task", error)
  }
  return null
}

export async function updateTask(taskId: string, updates: Partial<Task>) {
  const { user, isGuest } = getAuthState()

  if (isGuest || !user) {
    const tasks = getTasks().map(t => t.id === taskId ? { ...t, ...updates } : t)
    saveTasks(tasks)
    return
  }

  try {
    const body: any = {}
    if (updates.title !== undefined) body.title = updates.title
    if (updates.completed !== undefined) body.is_completed = updates.completed

    await fetch(`${API_URL}/tasks/${taskId}`, {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${getAuthState().token}`
      },
      body: JSON.stringify(body)
    })
  } catch (error) {
    console.error("Failed to update task", error)
  }
}

export async function deleteTask(taskId: string) {
  const { user, isGuest } = getAuthState()

  if (isGuest || !user) {
    const tasks = getTasks().filter(t => t.id !== taskId)
    saveTasks(tasks)
    return
  }

  try {
    await fetch(`${API_URL}/tasks/${taskId}`, {
      method: "DELETE",
      headers: {
        "Authorization": `Bearer ${getAuthState().token}`
      }
    })
  } catch (error) {
    console.error("Failed to delete task", error)
  }
}

export async function saveFocusSession(durationMinutes: number, taskId?: string) {
  const { user, isGuest } = getAuthState()
  if (isGuest || !user) return

  try {
    await fetch(`${API_URL}/focus_sessions`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        user_id: user.id,
        task_id: taskId ? parseInt(taskId) : null,
        duration_minutes: durationMinutes,
        start_time: new Date(Date.now() - durationMinutes * 60000).toISOString(),
        end_time: new Date().toISOString()
      })
    })
  } catch (error) {
    console.error("Failed to save focus session", error)
  }
}

